@section('scripts')
<script>
$(function(){
    function escapeHtml(text) {
        return text ? $('<div>').text(text).html() : '';
    }
    const panels = $('#filterPanel, #startDrawer, #completeSheet');
    function openPanel(id){ panels.addClass('hidden'); $(id).removeClass('hidden'); $('body').addClass('overflow-hidden'); }
    function closePanels(){ panels.addClass('hidden'); $('body').removeClass('overflow-hidden'); }
    $('[data-close-panel]').on('click', closePanels); panels.on('click', function(e){ if(e.target === this) closePanels(); });
    $('[data-open-filters]').on('click', () => openPanel('#filterPanel'));
    $('[data-open-start]').on('click', function(){ openPanel('#startDrawer'); const id=$(this).data('machine-id'); if(id) $(`#startBatchForm input[name=machine_id][value=${id}]`).prop('checked', true); });
    $('[data-open-complete]').on('click', function(){ $('#completeTitle').text($(this).data('batch-no')); $('#completeMeta').text(`${$(this).data('machine')} · ${$(this).data('grade')}`); $('#completeForm').attr('action', $(this).data('action')); openPanel('#completeSheet'); setTimeout(() => $('#completeForm input[name=output_bags]').focus(), 100); });
    $(document).on('keydown', e => { if(e.key === 'Escape') closePanels(); });

    function timers(){ $('.production-timer').each(function(){ const sec=Math.max(0,Math.floor((Date.now()-new Date($(this).data('start')).getTime())/1000)); $(this).text(`${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec%3600/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`); }); } timers(); setInterval(timers,1000);
    $('#batchQuickSearch').on('input', function(){ const q=this.value.toLowerCase(); $('#productionTable tbody tr').each(function(){ $(this).toggle($(this).text().toLowerCase().includes(q)); }); });
    $('#densityToggle').on('click', function(){ $('#productionTable').toggleClass('compact-table'); });
    $('#drawerGrade').on('change', function(){ const url=$(this).find(':selected').data('url'); if(!url){ $('#formulaPreview').addClass('hidden'); return; } $('#formulaPreview').removeClass('hidden'); $('#formulaMeta').text('Loading formula…'); $('#formulaItems').html('<div class="h-10 animate-pulse rounded-xl bg-blue-100"></div>'); $.get(url).done(function(data){ $('#formulaMeta').text(`Version ${data.version} · ${data.bag_size_name}`); $('#formulaItems').html(data.items.map(i => `<div class="flex items-center justify-between rounded-xl bg-white px-3 py-2 text-[10px]"><span class="font-bold text-slate-600">${escapeHtml(i.raw_material_name)}</span><strong class="font-mono text-slate-800">${i.quantity} ${escapeHtml(i.unit_code)}</strong></div>`).join('')); }).fail(xhr => { $('#formulaMeta').text(xhr.responseJSON?.error || 'Formula unavailable'); $('#formulaItems').empty(); }); });

    function ajaxForm(form, button, error){ form.on('submit', function(e){ e.preventDefault(); const btn=$(button), original=btn.html(); $(error).addClass('hidden'); btn.prop('disabled',true).html('<span class="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white"></span><span>Working…</span>'); $.ajax({url:this.action, method:$(this).find('input[name=_method]').val() || 'POST', data:$(this).serialize(), headers:{'X-Requested-With':'XMLHttpRequest'}}).done(res => { window.location.href=res.redirect_url; }).fail(xhr => { const msg=xhr.responseJSON?.message || Object.values(xhr.responseJSON?.errors || {}).flat()[0] || 'Please check the form and try again.'; $(error).text(msg).removeClass('hidden'); btn.prop('disabled',false).html(original); window.renderHeroicons(btn[0]); }); }); }
    ajaxForm($('#startBatchForm'),'#startSubmit','#startError'); ajaxForm($('#completeForm'),'#completeSubmit','#completeError');
});
</script>
@endsection
